// src/solver/gencoLines.js
// Per-line loading (and bus voltage) that the GENCO checkpoint estimates, next to the AC, for the intact network and for every single-line outage
// (file generated by backend/tools/export_genco_lines.py). It feeds the "GENCO" view of the diagram and the AC view of the static demo.
// Pure functions, tested without a network. State of each entry: AC-OPF base dispatch, one line out, reference bus absorbing the imbalance, no redispatch.

const cache = new Map();

/** Loads the file of network `grid` (e.g. 'case118_ieee'); null when there is none. Results are cached. */
export async function loadGencoLines(grid) {
    if (!grid) return null;
    if (!cache.has(grid)) {
        let data = null;
        try { data = (await import(`../data/genco_lines_${grid}.json`)).default; } catch { data = null; }
        cache.set(grid, data);
    }
    return cache.get(grid);
}

/**
 * Which stored state describes the current topology: 'base' (no faults), '<branch id>' (exactly one line open by the user, no faulted bus) or null.
 * Lines opened automatically by a bus fault (`openByFault`) do not count as an opened line.
 */
export function outageKey(branches, faultNodes) {
    if (faultNodes && faultNodes.size > 0) return null;
    const open = (branches || []).filter(b => b.state === 0 && !b.openByFault);
    if (open.length === 0) return 'base';
    return open.length === 1 ? String(open[0].id) : null;
}

/** Stored entry of a topology key, or null (outage not in the file: it islands buses or the AC did not converge there). */
export function storedState(data, key) {
    if (!data || key == null) return null;
    return key === 'base' ? data.base : (data.outages?.[key] || null);
}

/** Mean and maximum |GENCO − AC| loading over the lines in service (% points) for an entry. */
export function gencoErrorPoints(entry) {
    if (!entry) return null;
    let sum = 0, max = 0, n = 0;
    entry.ac.forEach((a, i) => {
        if (!(a > 0)) return;                                  // line out of service (0) or without limit
        const d = Math.abs(entry.genco[i] - a);
        sum += d; n += 1; if (d > max) max = d;
    });
    return { mean: n ? sum / n : 0, max, lines: n };
}

/**
 * Result in the interface format for the AC ('ac') or GENCO ('genco') values of a stored entry. Everything comes from the file: the loading and the active and
 * reactive flow of every branch, the voltage and angle of every bus and the generation at the generator buses. GENCO predicts only the voltages; the flows and the
 * reference-bus generation were computed from them with the same admittances as the AC (see backend/tools/export_genco_lines.py).
 */
export function composeStoredResult(entry, method, branches, data) {
    const loading = entry[method], pf = entry[`${method}Pf`], qf = entry[`${method}Qf`];
    const vm = entry[`${method}Vm`], va = entry[`${method}Va`], pg = entry[`${method}Pg`], qg = entry[`${method}Qg`];
    const genIndex = new Map((data.genBus || []).map((no, i) => [no, i]));
    const nodes = {};
    (data.busNo || []).forEach((no, i) => {
        nodes[no] = { v: vm[i], angle: va[i], unit: 'MW' };
        const k = genIndex.get(no);
        if (k !== undefined) { nodes[no].pg = pg[k]; nodes[no].qg = qg[k]; }
    });
    const rate = new Map((branches || []).map(b => [b.id, b.rateA || 0]));
    const lines = {};
    (branches || []).forEach(b => {
        const i = b.id;
        const out = !(loading[i] > 0) && pf[i] === 0 && qf[i] === 0;          // branch out of service (the backend also returns zeros)
        lines[i] = out
            ? { current: 0, percentage: 0, pFlow: 0, qFlow: 0, limitCurrent: rate.get(i) || 0, unit: 'MW' }
            : { current: Math.max((loading[i] / 100) * (rate.get(i) || 0), 0.002), percentage: loading[i], pFlow: pf[i] * 1000, qFlow: qf[i] * 1000, limitCurrent: rate.get(i) || 0, unit: 'MW' };
    });
    const genMW = (pg || []).reduce((x, y) => x + y, 0);
    return { nodes, lines, summary: { mode: method.toUpperCase(), source: 'precomputed', servedMW: data.loadMW, lostMW: 0, genMW, energizedBuses: (data.busNo || []).length, violations: { overload: [], voltage: [], qgen: [] } } };
}

/** Active generation of the reference bus (MW) in an entry for each method, and their difference (GENCO − AC). */
export function referenceGeneration(entry, data) {
    if (!entry || !data) return null;
    const k = (data.genBus || []).indexOf(data.refBus);
    if (k < 0) return null;
    return { bus: data.refBus, ac: entry.acPg[k], genco: entry.gencoPg[k], diff: entry.gencoPg[k] - entry.acPg[k] };
}
